"""Original HLH assessment questions; continues Still/MAS chapter."""
from create_rheum_still_mas import rows,q,S,H,ref
AH=ref('Histiocyte Society adult HLH recommendations','https://doi.org/10.1182/blood.2018894618')

q('A critically ill patient has persistent fever, splenomegaly, bicytopenia, hepatitis, triglyceride elevation, low fibrinogen and rapidly rising ferritin. Which syndrome requires urgent assessment alongside sepsis?', 'Hemophagocytic lymphohistiocytosis',[
 ('Isolated iron overload','This does not explain the acute cytopenic coagulopathic multiorgan syndrome.'),('Uncomplicated viral pharyngitis','This does not account for the severity and organ pattern.'),('Primary immune thrombocytopenia alone','An isolated platelet disorder does not explain bicytopenia, hepatitis and the full hyperinflammatory picture.')],
 'Recognize an evolving hyperinflammatory organ-failure syndrome','**HLH can mimic sepsis, coexist with infection or be triggered by it.**',['Malignancy, rheumatic disease and genetic immune defects are other important contexts.','No single ferritin threshold proves the diagnosis.'], '**Investigate triggers and begin severity-appropriate treatment promptly.**',['Selected severe or EBV/malignancy-associated cases may require etoposide-based therapy under specialist care.','Tailor immune treatment rather than apply one pediatric protocol indiscriminately to every adult.'],[['Syndrome','Fever/cytopenias/organ injury'],['Trigger','Infectious, malignant, immune or genetic'],['Treatment','Urgency and mechanism-directed']],[H,AH],style='clinical_scenario')

q('What is a key limitation of using HLH-2004 criteria in adults?', 'They were developed for pediatric HLH and must be interpreted with clinical judgment rather than used as an inflexible treatment gate',[
 ('They consist only of ferritin above 500','They include several clinical, biochemical, immune and pathological items.'),('They require hemophagocytosis in every patient','A molecular diagnosis or sufficient other criteria can establish the framework without marrow hemophagocytosis.'),('They exclude all infection-associated HLH','Infection can trigger HLH.')],
 'A framework is useful but not a substitute for urgent judgment','**HLH-2004 uses a molecular diagnosis or five of eight criteria.**',['Adult disease can be evolving before all thresholds are met.','Critical illness and underlying cancer can also generate overlapping abnormalities.'], '**Integrate the pattern, trajectory and alternative diagnoses.**',['Specialized tests should be sent when helpful but may return too late for immediate decisions.','Do not delay treatment of a deteriorating probable syndrome solely to complete a checklist.'],[['HLH-2004','Structured framework'],['Adult context','Requires interpretation'],['Clinical trajectory','Can justify action before complete criteria']],[AH,H])

q('A marrow aspirate in suspected HLH shows no hemophagocytosis. Which statement is correct?', 'HLH remains possible; hemophagocytosis is neither required in every case nor specific when present',[
 ('The negative aspirate definitively excludes HLH','Sensitivity is incomplete and findings may evolve.'),('Any later single phagocytic macrophage will prove HLH regardless of context','Hemophagocytosis can occur in other critical illnesses.'),('Marrow investigation has no further value','It can identify malignancy, infection or other cytopenia mechanisms.')],
 'Use marrow for the differential as well as a criterion','**Absence of hemophagocytosis does not rule out HLH.**',['The syndrome can be diagnosed through the broader clinical/laboratory pattern.','A positive finding also needs context.'], '**Preserve diagnostic material for the suspected trigger.**',['Consider flow cytometry, histology, microbiology and molecular tests as indicated.','Treatment decisions should reflect organ threat and overall probability.'],[['Negative hemophagocytosis','Not an exclusion'],['Positive finding','Not uniquely specific'],['Marrow','Can reveal the underlying disease']],[H,AH],style='clinical_scenario')

q('What is the appropriate role of the HScore in suspected adult secondary HLH?', 'It estimates probability and supports clinical assessment but does not independently establish or exclude every case',[
 ('It is a molecular test for a perforin mutation','It is a clinical/laboratory score, not genetic testing.'),('A low early score permanently excludes evolving HLH','Features may emerge over time and early treatment can alter findings.'),('It replaces the search for infection or malignancy','Finding the trigger remains essential.')],
 'Scores organize evidence rather than end diagnostic reasoning','**HScore combines features such as fever, organomegaly, cytopenias and biochemical changes.**',['Its performance varies with the population and timing.','Missing data and treatment exposure can affect interpretation.'], '**Use serial clinical and organ assessment.**',['Do not delay urgent care while waiting for one score component.','Keep competing diagnoses and triggers under review.'],[['HScore','Probability support'],['Trajectory','Important in evolving disease'],['Trigger evaluation','Still necessary']],[H,ref('Original HScore development and validation','https://doi.org/10.1002/art.38690')])

q('An adult with HLH has weight loss, marked lymphadenopathy and a monoclonal lymphoid population. What is the key etiological priority?', 'Establish and treat an underlying lymphoma while controlling hyperinflammation',[
 ('Assume autoimmune MAS solely because ferritin is high','The lymphoid findings make malignancy a major concern.'),('Treat ferritin as an isolated iron problem','This does not address the inflammatory syndrome or malignant driver.'),('Avoid tissue diagnosis because immune treatment always makes etiology irrelevant','Trigger-directed treatment can determine outcome.')],
 'Controlling the syndrome is not the same as treating its driver','**Lymphoma is an important adult HLH trigger.**',['Obtain informative tissue promptly when safe.','Some urgent immune treatment may be necessary before every test is complete, so coordinate sampling and therapy.'], '**Plan hematological and hyperinflammatory treatment together.**',['Consider EBV and other co-triggers.','Monitor organ function and treatment toxicity closely.'],[['HLH control','Urgent inflammatory care'],['Lymphoma diagnosis','Tissue and immunophenotype'],['Definitive management','Treat the driver']],[AH,H],style='clinical_scenario')

q('Which statement about inherited immune defects in HLH is correct?', 'Genetic predisposition can present in adulthood, particularly with recurrent, familial or unusual disease',[
 ('All genetic HLH presents before the first birthday','Hypomorphic and other variants can present later.'),('A detected infection excludes genetic susceptibility','An infection may trigger disease in a predisposed individual.'),('Genetic evaluation cannot affect treatment or transplant decisions','It can materially change long-term management and family counseling.')],
 'Age alone should not close the genetic question','**Primary cytotoxic-pathway disorders can present beyond childhood.**',['Recurrent episodes, family history and selected immune phenotypes increase suspicion.','Perforin/granule-exocytosis and other immune pathways may be involved.'], '**Consider specialist genetic and functional testing early when indicated.**',['Some patients require a definitive HSCT pathway.','Do not postpone acute organ support while the genetic workup proceeds.'],[['Adult onset','Does not exclude inherited disease'],['Trigger','Can coexist with predisposition'],['Diagnosis','Can change definitive treatment']],[H,AH])

if __name__=='__main__':print(f'Autoinflammatory/HLH cumulative draft: {len(rows)} questions')
